script:
function formatNumber(n){return Number.isInteger(n)?n.toString():parseFloat(n.toFixed(4)).toString()}
function calcBasic(){var p=parseFloat(document.getElementById('basic-percent').value),n=parseFloat(document.getElementById('basic-number').value),r=document.getElementById('basic-result'),f=document.getElementById('basic-formula');if(!isNaN(p)&&!isNaN(n)){var res=(p/100)*n;r.textContent=formatNumber(res);f.textContent='('+p+' \u00f7 100) \u00d7 '+n+' = '+formatNumber(res)}else{r.textContent='\u2013';f.textContent=''}}
function calcReverse(){var part=parseFloat(document.getElementById('reverse-part').value),whole=parseFloat(document.getElementById('reverse-whole').value),r=document.getElementById('reverse-result'),f=document.getElementById('reverse-formula');if(!isNaN(part)&&!isNaN(whole)&&whole!==0){var res=(part/whole)*100;r.textContent=formatNumber(res)+'%';f.textContent='('+part+' \u00f7 '+whole+') \u00d7 100 = '+formatNumber(res)+'%'}else{r.textContent='\u2013';f.textContent=''}}
function calcWhole(){var val=parseFloat(document.getElementById('whole-value').value),pct=parseFloat(document.getElementById('whole-percent').value),r=document.getElementById('whole-result'),f=document.getElementById('whole-formula');if(!isNaN(val)&&!isNaN(pct)&&pct!==0){var res=val/(pct/100);r.textContent=formatNumber(res);f.textContent=val+' \u00f7 ('+pct+' \u00f7 100) = '+formatNumber(res)}else{r.textContent='\u2013';f.textContent=''}}
function calcChange(){var from=parseFloat(document.getElementById('change-from').value),to=parseFloat(document.getElementById('change-to').value),r=document.getElementById('change-result'),f=document.getElementById('change-formula');if(!isNaN(from)&&!isNaN(to)&&from!==0){var pct=((to-from)/Math.abs(from))*100,sign=pct>=0?'+':'';r.textContent=sign+formatNumber(pct)+'%';f.textContent='(('+to+' - '+from+') \u00f7 '+from+') \u00d7 100 = '+sign+formatNumber(pct)+'%'}else{r.textContent='\u2013';f.textContent=''}}
function calcDiff(){var v1=parseFloat(document.getElementById('diff-value1').value),v2=parseFloat(document.getElementById('diff-value2').value),r=document.getElementById('diff-result'),a=document.getElementById('diff-absolute'),f=document.getElementById('diff-formula');if(!isNaN(v1)&&!isNaN(v2)){var avg=(v1+v2)/2,diff=Math.abs(v1-v2),pct=avg!==0?(diff/avg)*100:0;r.textContent=formatNumber(pct)+'%';if(a)a.textContent=formatNumber(diff);if(f)f.textContent='|'+v1+' - '+v2+'| \u00f7 (('+v1+' + '+v2+') \u00f7 2) \u00d7 100 = '+formatNumber(pct)+'%'}else{r.textContent='\u2013';if(a)a.textContent='\u2013';if(f)f.textContent=''}}
function clearBasic(){document.getElementById('basic-percent').value='';document.getElementById('basic-number').value='';calcBasic();document.getElementById('basic-percent').focus()}
function clearReverse(){document.getElementById('reverse-part').value='';document.getElementById('reverse-whole').value='';calcReverse();document.getElementById('reverse-part').focus()}
function clearWhole(){document.getElementById('whole-value').value='';document.getElementById('whole-percent').value='';calcWhole();document.getElementById('whole-value').focus()}
function clearChange(){document.getElementById('change-from').value='';document.getElementById('change-to').value='';calcChange();document.getElementById('change-from').focus()}
function clearDiff(){document.getElementById('diff-value1').value='';document.getElementById('diff-value2').value='';calcDiff();document.getElementById('diff-value1').focus()}
